import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Users, Package, Activity } from 'lucide-react';
import { workerAPI, productAPI, machineAPI } from '../services/api';

const Dashboard = () => {
  const [stats, setStats] = useState({
    workers: 0,
    products: 0,
    machines: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const [workers, productStats, machines] = await Promise.all([
          workerAPI.getAll(),
          productAPI.getStats(),
          machineAPI.getAll()
        ]);

        setStats({
          workers: workers.data?.data?.length || workers.data?.length || 0,
          products: productStats.data?.data?.running || productStats.data?.running || 0, // Only running products
          machines: machines.data?.data?.length || machines.data?.length || 0
        });
      } catch (error) {
        // Error fetching stats
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  const dashboardCards = [
    {
      title: 'Workers',
      count: stats.workers,
      icon: Users,
      color: '#007bff',
      link: '/workers'
    },
    {
      title: 'Running Products',
      count: stats.products,
      icon: Package,
      color: '#28a745',
      link: '/products'
    },
    {
      title: 'Machines',
      count: stats.machines,
      icon: Activity,
      color: '#fd7e14',
      link: '/meters'
    }
  ];

  if (loading) {
    return <div className="loading">Loading dashboard...</div>;
  }

  return (
    <div className="container">
      <h1 className="mb-20">Dashboard</h1>
      
      <div className="grid grid-3">
        {dashboardCards.map((card, index) => {
          const IconComponent = card.icon;
          return (
            <Link key={index} to={card.link} style={{ textDecoration: 'none' }}>
              <div className="card" style={{ 
                borderLeft: `4px solid ${card.color}`,
                cursor: 'pointer',
                transition: 'transform 0.2s',
              }}
              onMouseEnter={(e) => e.currentTarget.style.transform = 'translateY(-2px)'}
              onMouseLeave={(e) => e.currentTarget.style.transform = 'translateY(0)'}
              >
                <div className="flex justify-between items-center">
                  <div>
                    <h3 style={{ color: card.color, marginBottom: '10px' }}>
                      {card.title}
                    </h3>
                    <p style={{ fontSize: '2rem', fontWeight: 'bold', margin: 0 }}>
                      {card.count}
                    </p>
                  </div>
                  <IconComponent size={48} color={card.color} />
                </div>
              </div>
            </Link>
          );
        })}
      </div>

      <div className="grid grid-2 mt-20">
        <div className="card">
          <h3>Quick Actions</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '15px' }}>
            <Link to="/workers" className="btn btn-primary">Add New Worker</Link>
            <Link to="/products" className="btn btn-secondary">Manage Products</Link>
            <Link to="/meters" className="btn btn-primary">Manage Machines</Link>
          </div>
        </div>

        <div className="card">
          <h3>System Overview</h3>
          <p style={{ marginTop: '15px', color: '#666' }}>
            Welcome to the Fabric Management System. Use the navigation above to manage 
            workers, products, and production machines.
          </p>
          <p style={{ marginTop: '10px', color: '#666' }}>
            The system helps track fabric production, worker performance, and 
            machine operations for efficient manufacturing management.
          </p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;